// Induced Paley(17) embeddings into a graph6 host of order <=62. Search all embeddings up to the choice of minimum seed vertex and minimum red neighbor there (translations and nonzero square multipliers). Record best red/blue K4-free extension of any embedded seed when requested.
use std::{env,fs};
fn bits(x:u64)->impl Iterator<Item=usize>{let mut y=x;std::iter::from_fn(move||if y==0{None}else{let i=y.trailing_zeros() as usize;y&=y-1;Some(i)})}
fn graph(l:&str)->Vec<u64>{let b=l.as_bytes();let n=(b[0]-63) as usize;let mut a=vec![0;n];let mut t=0;for j in 1..n{for i in 0..j{if (b[1+t/6]-63)>>(5-t%6)&1!=0{a[i]|=1<<j;a[j]|=1<<i}t+=1}}a}
fn search(a:&[u64],s:&[u64;17],free:u64,d:[u64;17],used:u64,out:&mut Vec<u64>){if free==0{out.push(used);return}let i=bits(free).min_by_key(|&i|(d[i].count_ones(),i)).unwrap();let rem=free^(1<<i);'v:for v in bits(d[i]){let mut e=d;for j in bits(rem){let red=s[i]>>j&1!=0;let mut mask=if red{a[v]}else{!a[v]&!(1<<v)};if i==0 || i==1&&s[0]>>j&1!=0{mask&=(!0u64)<<(v+1)}e[j]&=mask;if e[j]==0{continue 'v}}search(a,s,rem,e,used|1<<v,out)}}
fn main(){let s:[u64;17]=std::array::from_fn(|i| (1..17).fold(0,|m,j|m|1<<((i+j*j)%17)));let mut n=0;let mut hist=std::collections::BTreeMap::new();for l in fs::read_to_string(env::args().nth(1).unwrap()).unwrap().lines(){let a=graph(l);let mut out=vec![];search(&a,&s,(1<<17)-1,[(1<<a.len())-1;17],0,&mut out);out.sort_unstable();out.dedup();n+=1;*hist.entry(out.len()).or_insert(0)+=1;if !out.is_empty(){println!("{n} {} {}",out.len(),out[0]);if env::args().nth(2).as_deref()==Some("--all"){println!("seeds {out:?}")}}}eprintln!("rows {n} histogram {hist:?}")}
